/*! Minimal screen wake-lock helper -- replaces NoSleep.js v0.12.0.
 *
 * This page is served from the Pico's Wi-Fi access point over plain http://,
 * which browsers do NOT treat as a "secure context". The Wake Lock API
 * (navigator.wakeLock) is gated on secure contexts, so it is simply absent here
 * on every browser -- desktop and mobile alike. The one technique that still
 * works over HTTP is keeping a tiny muted, looping, inline <video> playing:
 * browsers hold the backlight on while a video plays.
 *
 * Why the old vendored NoSleep.js kept letting phones sleep:
 *   1. It never attached its <video> to the DOM. Desktop browsers tolerate a
 *      detached media element; iOS Safari and Firefox-for-iOS refuse to start
 *      playback unless the element is in the document.
 *   2. Its <video> was zero-size / fully transparent. iOS only holds the screen
 *      awake for a video it considers on-screen and rendering, so an invisible
 *      one often does nothing.
 *   3. It armed the video exactly once. iOS drops video playback on phone-lock,
 *      app-switch and Low Power Mode transitions -- frequently without a 'pause'
 *      event -- and never resumes it, so the keep-awake died after the first
 *      screen-lock.
 *
 * This version:
 *   - keeps a real 2x2px, ~1% opacity <video> pinned in the DOM;
 *   - re-kicks playback on visibilitychange, on every tap/click, and from a 4s
 *     watchdog interval (the only thing that catches a silent iOS drop);
 *   - on a genuine user gesture, unmutes the video's (silent) audio track at a
 *     volume too low to hear (_boostAudio()). Some iOS versions stop counting
 *     a fully-muted, silent video as "active media" and let the display
 *     auto-lock out from under it after a few minutes even while it's still
 *     playing; a video with an active (if inaudible) audio track is reported
 *     to hold up better. Falls back to muted if the browser refuses the
 *     unmuted autoplay;
 *   - still prefers the real Wake Lock API when available (HTTPS / localhost),
 *     falling back to the video if the request rejects.
 *
 * Not fixable from here: iOS **Low Power Mode** disables video keep-awake
 * entirely, and third-party iOS browsers (this app wraps WKWebView, same as
 * Firefox/Chrome-for-iOS) may simply not get the same "suppress the idle
 * timer during video playback" system privilege Safari itself has -- in which
 * case no amount of JS here can fix it. If a device still sleeps at a fixed
 * interval that matches its Settings -> Display & Brightness -> Auto-Lock
 * value, that's the tell; setting Auto-Lock to "Never" on the device running
 * this page is the reliable fix, and worth doing for competition day
 * regardless of whether the tricks above help.
 *
 * API is a drop-in subset of NoSleep.js: `new NoSleep()`, `.enable()` (returns a
 * Promise, must be called from a user gesture), `.disable()`.
 */
(function (global) {
    'use strict';

    var WEBM = 'data:video/webm;base64,';
    var MP4 = 'data:video/mp4;base64,';

    var hasWakeLock = ('wakeLock' in navigator);

    function NoSleep() {
        this.enabled = false;
        this._wakeLock = null;
        this._video = null;
        this._watchdog = null;
        this._onVisibility = this._onVisibility.bind(this);
        this._onGesture = this._onGesture.bind(this);
        this._kick = this._kick.bind(this);
    }

    NoSleep.prototype._buildVideo = function () {
        if (this._video) return this._video;
        var video = document.createElement('video');
        video.setAttribute('title', 'keep-awake');
        video.setAttribute('playsinline', '');
        video.setAttribute('webkit-playsinline', '');   // older iOS WebKit
        video.setAttribute('muted', '');
        video.setAttribute('autoplay', '');
        video.setAttribute('loop', '');
        video.muted = true;          // safe default: playable without a gesture
        video.defaultMuted = true;
        video.loop = true;
        video.playsInline = true;
        video.volume = 0.01;         // used once _boostAudio() unmutes it
        // iOS only holds the screen awake for a video it considers on-screen and
        // actually rendering. A display:none / zero-size / fully-transparent /
        // z-index:-1-behind-an-opaque-body element does NOT reliably count, so
        // pin a real 2x2px box in a corner, on top, at ~1% opacity.
        video.style.cssText =
            'position:fixed;right:0;bottom:0;width:2px;height:2px;' +
            'min-width:2px;min-height:2px;opacity:0.01;pointer-events:none;' +
            'border:0;padding:0;margin:0;z-index:2147483647;';

        [['webm', WEBM], ['mp4', MP4]].forEach(function (pair) {
            var source = document.createElement('source');
            source.src = pair[1];
            source.type = 'video/' + pair[0];
            video.appendChild(source);
        });

        // Manual loop: the `loop` attribute is unreliable on some iOS versions,
        // and iOS stops honouring the keep-awake the moment playback ends. Seek
        // back near the end so it never actually reaches the end.
        video.addEventListener('timeupdate', function () {
            if (video.duration && video.currentTime > video.duration - 0.4) {
                video.currentTime = 0;
            }
        });
        // Only re-kick on 'ended' (rare with loop set). Deliberately NOT on
        // 'pause': under iOS Low Power Mode play() resolves then pauses again
        // immediately, which would spin. The 4s watchdog covers that case.
        video.addEventListener('ended', this._kick);

        document.body.appendChild(video);
        video.load();
        this._video = video;
        return video;
    };

    // Resume the keep-awake video if it isn't playing. Safe to call anytime;
    // does nothing unless we're enabled and the video has actually stopped.
    NoSleep.prototype._kick = function () {
        if (!this.enabled || !this._video) return;
        var self = this;
        var video = this._video;
        if (video.paused || video.ended) {
            var p = video.play();
            if (p && typeof p.catch === 'function') {
                p.catch(function () {
                    // An unmuted resume without a fresh gesture can be refused;
                    // fall back to muted so playback (and the idle-timer block
                    // it provides) doesn't just stop. The next tap re-boosts it.
                    if (!video.muted) {
                        video.muted = true;
                        self._audioBoosted = false;
                        video.play().catch(function () {});
                    }
                });
            }
        }
    };

    // Some iOS versions stop treating a fully-muted, silent video as "active
    // media" after a few minutes and let the display auto-lock anyway, even
    // though it's still playing. The bundled clips (from NoSleep.js) already
    // carry a silent audio track; unmuting it at a volume too low to hear
    // makes the element look like real playing media, which several reports
    // say keeps the idle-timer suppressed for the long haul. This can only be
    // called from a genuine user gesture (autoplay-with-sound requires one).
    NoSleep.prototype._boostAudio = function () {
        if (!this._video || this._audioBoosted) return;
        var self = this;
        var video = this._video;
        video.muted = false;
        var p = video.play();
        if (p && typeof p.then === 'function') {
            p.then(function () { self._audioBoosted = true; }).catch(function () {
                // Refused -- revert to muted so the watchdog can keep going.
                video.muted = true;
                video.play().catch(function () {});
            });
        } else {
            this._audioBoosted = true;
        }
    };

    NoSleep.prototype._playVideo = function () {
        var video = this._buildVideo();
        var p = video.play();
        return (p && typeof p.then === 'function') ? p : Promise.resolve();
    };

    NoSleep.prototype._startWatchdog = function () {
        if (this._watchdog) return;
        // iOS silently drops video playback on phone-lock, app-switch and some
        // Low Power Mode transitions without firing a 'pause' we can catch, so
        // poll and re-kick. 4s is frequent enough to re-arm before the display
        // sleep timer (30s+) elapses, cheap enough to ignore.
        this._watchdog = setInterval(this._kick, 4000);
    };

    NoSleep.prototype._stopWatchdog = function () {
        if (this._watchdog) { clearInterval(this._watchdog); this._watchdog = null; }
    };

    NoSleep.prototype._requestWakeLock = function () {
        var self = this;
        return navigator.wakeLock.request('screen').then(function (lock) {
            self._wakeLock = lock;
            lock.addEventListener('release', function () { self._wakeLock = null; });
        });
    };

    NoSleep.prototype._onVisibility = function () {
        if (document.visibilityState !== 'visible' || !this.enabled) return;
        // Coming back to the foreground: the OS has dropped whatever we held.
        if (hasWakeLock && !this._wakeLock) {
            this._requestWakeLock().catch(function () {});
        }
        this._kick();
    };

    NoSleep.prototype._onGesture = function () {
        // A real user gesture is the one context where iOS will always let
        // play() succeed, so re-kick on every tap/click while enabled, and use
        // the gesture to try upgrading to the unmuted "boosted" video.
        this._kick();
        if (this.enabled) this._boostAudio();
    };

    NoSleep.prototype.enable = function () {
        var self = this;
        this.enabled = true;
        document.addEventListener('visibilitychange', this._onVisibility);
        document.addEventListener('touchstart', this._onGesture, { passive: true });
        document.addEventListener('touchend', this._onGesture, { passive: true });
        document.addEventListener('click', this._onGesture);
        this._startWatchdog();

        // Always run the video on iOS/insecure origins. Only skip it when a real
        // Wake Lock is in hand (secure context) -- that one genuinely works and
        // costs no battery on a decoded 2px clip... but the clip is near-free
        // anyway, so on any failure we fall straight back to it.
        var attempt = hasWakeLock
            ? this._requestWakeLock().catch(function () { return self._playVideo(); })
            : this._playVideo();

        // enable() is only ever called from inside a click/keydown handler
        // (see app.js), so this still counts as the user gesture autoplay-
        // with-sound needs.
        if (!hasWakeLock) self._boostAudio();

        return Promise.resolve(attempt).catch(function (err) {
            // Nothing else to try -- surface it so callers can log if they want.
            self.enabled = false;
            self._stopWatchdog();
            throw err;
        });
    };

    NoSleep.prototype.disable = function () {
        this.enabled = false;
        this._stopWatchdog();
        document.removeEventListener('visibilitychange', this._onVisibility);
        document.removeEventListener('touchstart', this._onGesture);
        document.removeEventListener('touchend', this._onGesture);
        document.removeEventListener('click', this._onGesture);

        if (this._wakeLock) {
            try { this._wakeLock.release(); } catch (e) { /* already gone */ }
            this._wakeLock = null;
        }
        if (this._video) {
            this._video.pause();
        }
    };

    global.NoSleep = NoSleep;
})(this);
